package com.nvv.mediadata.data.model.tmdbimport java.time.LocalDatesealed interface Media {	val adult: Boolean	val id: Long	val background: String?	val poster: String?	val originalLanguage: String	val genres: List<Int>	/// TITLE	val title: String	val originalTitle: String	val overview: String	val popularity: Double	val releaseDate: LocalDate?	val voteAverage: Double	val voteCount: Int}fun Media.getPoster() : String {	return BaseURLTheMovieDatabaseImage + PosterTheMovieDatabase + (this.poster ?: "")}fun Media.getBackground() : String {	return BaseURLTheMovieDatabaseImage + BackgroundTheMovieDatabase + (this.background ?: "")}